import java.util.ArrayList;
import java.util.List;

public class Solution {
    public static List<Integer> capPerKey(List<String> keys, int limit) {
        if (limit < 0) {
            throw new IllegalArgumentException("limit must be non-negative");
        }
        if (keys == null || keys.isEmpty()) {
            return new ArrayList<>();
        }
        int n = keys.size();
        int[] idx = new int[n];
        for (int i = 0; i < n; i++) {
            idx[i] = i;
        }
        int limitCount = 0;
        for (int i = 0; i < n; i++) {
            int j = i;
            while (j < n && limitCount < limit) {
                if (keys.get(j).equals(keys.get(i))) {
                    idx[j] = i;
                    limitCount++;
                    j++;
                } else {
                    break;
                }
            }
        }
        return new ArrayList<>(idx);
    }
}

